import"./hoisted.DWIkIr-H.js";document.querySelectorAll(".tab-btn").forEach(e=>{e.addEventListener("click",()=>{const a=e.dataset.tab;document.querySelectorAll(".tab-btn").forEach(t=>{t.setAttribute("aria-selected",t===e?"true":"false"),t.classList.toggle("text-tertiary",t===e),t.classList.toggle("border-tertiary",t===e),t.classList.toggle("bg-surface",t===e),t.classList.toggle("text-muted",t!==e),t.classList.toggle("border-transparent",t!==e)}),document.querySelectorAll(".tab-panel").forEach(t=>{const r=t.id===`tab-${a}`;t.classList.toggle("hidden",!r),t.classList.toggle("block",r)})})});document.querySelectorAll('.tab-btn[aria-selected="true"]').forEach(e=>{e.classList.add("text-tertiary","border-tertiary","bg-surface"),e.classList.remove("text-muted","border-transparent")});document.querySelectorAll('.tab-btn[aria-selected="false"]').forEach(e=>{e.classList.add("text-muted","border-transparent")});
